#include "combat/Simulation.hpp"
#include "core/BalancePreset.hpp"
#include <chrono>
#include <fstream>
#include <iostream>
#include <sstream>
using namespace dw;
namespace {
const auto Root=std::filesystem::path(DEATHWARD_TEST_ROOT);
void check(bool b,const char *why){if(!b)throw std::runtime_error(why);}
void ticks(Simulation &s,int n,float dt=Tick){for(int i=0;i<n;++i)s.step({},dt);}
Simulation canyon(float scale=1,int lo=7,int hi=9,uint64_t seed=940,int floor=0){return Simulation(seed,1,{},MissionTheme::Canyon,true,false,WitnessAccount::None,floor,ExpeditionPacing::Compact,defaultMechanics(),scale,lo,hi,.26f,true,1,true,true,true,true,true,true,1,1,MonstroTuning{},DukeTuning{true},false,255,RoomPropsTuning{1});}
std::vector<std::vector<int>> rows(const char *name){std::ifstream f(Root/"docs/reports/isaac-first-floor-parity/d14a19-golden-keys/source"/name);check(bool(f),"native CSV exists");std::string line;std::getline(f,line);std::vector<std::vector<int>> all;while(std::getline(f,line)){std::replace(line.begin(),line.end(),',',' ');std::istringstream in(line);std::vector<int> r;int x;while(in>>x)r.push_back(x);all.push_back(r);}return all;}
std::pair<int,int> lockedApproach(Simulation &s){for(size_t i=0;i<s.arena.passages.size();++i){const auto &door=s.arena.passages[i];if(!door.locked)continue;for(int side=0;side<2;++side){const auto kind=s.arena.rooms[size_t(door.rooms[size_t(side)])].kind;if(kind==RoomKind::Shop||kind==RoomKind::Power)continue;s.jumpDebug(door.rooms[size_t(side)]);s.clearRoomDebug();s.player.position=s.arena.doorApproach(int(i),side);s.player.position.y=.85f;if(s.arena.passages[i].locked)return {int(i),side};}}throw std::runtime_error("natural later-floor lock absent");}
void nativeCollection(){
 const auto captured=rows("native-collection.csv");check(captured.size()==12,"12 native collection cases");
 for(const auto &row:captured){auto s=canyon();s.keys=row[0];s.goldenKey=row[1];check(s.spawnGoldenKey(s.player.position,42),"golden actor admitted");ticks(s,24,1.f/30);check(s.keys==row[0]&&s.goldenKey==bool(row[1])&&s.keyPickups[0].timing.phase==KeyTiming::Phase::Appear,"no early collection before Drop25");ticks(s,1,1.f/30);check(s.keys==row[2]&&s.goldenKey==bool(row[3])&&s.keyPickups[0].timing.phase==KeyTiming::Phase::Collect&&row[4]==1,"actual native golden flag/count result including99/duplicate");ticks(s,12,1.f/30);check(s.keyPickups.empty()&&s.keys==row[2]&&s.goldenKey,"Collect12 cleanup pays once");}
 for(int hz:{60,120}){auto s=canyon();s.keys=0;check(s.spawnGoldenKey(s.player.position,1),"timed golden admission");ticks(s,25*hz/30-1,1.f/hz);check(!s.goldenKey,"partition no early collection");ticks(s,1,1.f/hz);check(s.goldenKey&&s.keys==0,"partition Drop25 collection");ticks(s,12*hz/30,1.f/hz);check(s.keyPickups.empty(),"partition cleanup");}
 std::cout<<"PASS12 native collections / counts0..99 / duplicates /30,60,120Hz timing\n";
}
void spending(){const auto captured=rows("native-spending.csv");check(captured.size()==12,"12 native key spending cases");for(const auto &row:captured){auto s=canyon(1,7,9,993,1);const auto [i,side]=lockedApproach(s);s.keys=row[0];s.goldenKey=row[1];check(s.useDoor(i,side)==bool(row[3]),"native ordinary key-use success");check(s.keys==row[2]&&s.goldenKey==bool(row[1]),"native golden no-spend result");if(row[3])check(s.useDoor(i,side)&&s.keys==row[2],"repeat unlock cannot spend again");}
 for(int mode=0;mode<6;++mode){auto s=canyon(1,7,9,993,1);const auto [i,side]=lockedApproach(s);s.keys=0;s.goldenKey=true;s.checkpointNeeded=false;switch(mode){case 0:s.roomClear=false;break;case 1:s.arena.passages[size_t(i)].sealed[1-side]=true;s.arena.rebuildWalls();break;case 2:s.dead=true;break;case 3:s.player.position=add(s.player.position,{20,0,0});break;case 4:s.keyedDoorCost=6;break;case 5:{auto at=s.arena.doorApproach(i,1-side);s.arena.obstacles.push_back({add(at,{-1,-2,-1}),add(at,{1,3,1})});s.arena.rebuildWalls();break;}}check(!s.useDoor(i,side)&&s.keys==0&&s.goldenKey&&s.arena.passages[size_t(i)].locked&&!s.checkpointNeeded,"gold does not bypass ordinary admission/safety guards");}
 auto s=canyon(1,7,9,993,1);const auto [i,side]=lockedApproach(s);s.keys=0;s.goldenKey=true;s.keyedDoorCost=5;check(s.useDoor(i,side)&&s.keys==0,"gold also bypasses testing cost without consuming stock");
 std::cout<<"PASS12 native use cases /6 guarded failures / repeated and custom-cost use\n";
}
void natural(float scale,int lo,int hi){auto s=canyon(scale,lo,hi);s.jumpDebug(s.arena.shopRoom);s.step({});check(s.grabBags.size()==1,"natural gold bag stock");const auto at=s.grabBags[0].position;uint32_t seed=0;for(auto d:s.grabBags[0].contents)if(d.variant==30&&d.subtype==2)seed=d.seed;check(seed!=0,"natural golden outcome");std::cout<<"WITNESS seed940 scale="<<scale<<" room="<<s.room+1<<" gold_seed="<<seed<<'\n';
 s.moneyCollected=20;s.player.position=at;s.grabBagTuning.goldenKeys=false;ticks(s,2);check(s.grabBags[0].opened&&s.moneySpent==7,"paid once while gold disabled");for(auto d:s.grabBags[0].contents)if(d.variant==30&&d.subtype==2)check(!d.delivered,"disabled gold retains request");
 s.player.position=s.arena.rooms[size_t(s.room)].entry;s.grabBagTuning.goldenKeys=true;s.keyPickups.resize(1024);ticks(s,2);for(auto d:s.grabBags[0].contents)if(d.variant==30&&d.subtype==2)check(!d.delivered,"capacity retains gold identity");s.keyPickups.clear();ticks(s,1);auto gold=std::find_if(s.keyPickups.begin(),s.keyPickups.end(),[](auto &k){return k.sourceSubtype==2;});check(gold!=s.keyPickups.end()&&gold->seed==seed,"same seed delivered after reenable and capacity");const auto goldPosition=gold->position;check(!s.arena.path(s.player.position,goldPosition,.48f).empty(),"gold physically reachable");
 const int shop=s.room;const auto frame=gold->timing.frame;s.enterRoom(0);s.player.position=s.arena.rooms[0].entry;ticks(s,60);gold=std::find_if(s.keyPickups.begin(),s.keyPickups.end(),[](auto &k){return k.sourceSubtype==2;});check(gold!=s.keyPickups.end()&&gold->timing.frame==frame,"inactive gold actor pauses");s.enterRoom(shop);s.player.position=goldPosition;s.keys=99;s.grabBagTuning.goldenKeys=false;ticks(s,100);check(s.goldenKey&&s.keys==99,"born gold still collects at99 after live drop disable");check(s.moneySpent==7,"no extra charge for delayed gold");s.enterRoom(0);s.player.position=s.arena.rooms[0].entry;ticks(s,2);s.enterRoom(shop);s.player.position=s.arena.rooms[size_t(shop)].entry;ticks(s,2);check(s.goldenKey&&std::none_of(s.keyPickups.begin(),s.keyPickups.end(),[](auto &k){return k.sourceSubtype==2;}),"revisit retains flag without respawn");
 s.resizeRooms(scale,lo,hi,.27f);check(s.goldenKey&&s.keys==99&&!s.grabBagTuning.goldenKeys,"Apply retains owned floor resource and live settings");check(!s.advanceFloor()&&s.goldenKey,"failed descent preserves gold");s.jumpDebug(s.finalRoom());s.clearRoomDebug();s.step({});s.floorExitRequested=true;check(s.advanceFloor()&&!s.goldenKey&&s.keys==99&&!s.grabBagTuning.goldenKeys,"successful descent clears only gold flag, retains stock/config");
 std::cout<<"PASS natural bag/payment/toggle/capacity/room/Apply/floor scale "<<scale<<'\n';
}
void persistence(){const auto file=std::filesystem::temp_directory_path()/("dw-gold-key-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())+".json");auto p=BalancePreset::load(Root/"docs/reports/isaac-first-floor-parity/d14a18-bag-bombs/review-preset.json",defaultMechanics()->fingerprint());check(p.grabBags.goldenKeys&&p.defaultZoomPercent==165,"schema62 migration retains user settings");p.grabBags.goldenKeys=false;p.grabBags.bombFuse=1.05f;p.save(file);auto q=BalancePreset::load(file,p.mechanicsFingerprint);check(q.grabBags==p.grabBags&&q.revision()==p.revision(),"schema63 full roundtrip");std::ifstream in(file);std::string bytes((std::istreambuf_iterator<char>(in)),{});in.close();auto at=bytes.find("\"golden_keys\": true");check(at!=std::string::npos,"fixed golden reference present");bytes.replace(at,19,"\"golden_keys\": false");std::ofstream(file)<<bytes;bool rejected=false;try{BalancePreset::load(file,p.mechanicsFingerprint);}catch(...){rejected=true;}check(rejected,"altered golden reference rejected");std::filesystem::remove(file);std::cout<<"PASS schema62 migration/63 roundtrip and strict reference rejection\n";}
}
int main(){try{std::cout<<std::unitbuf;nativeCollection();spending();for(auto [scale,lo,hi]:{std::tuple{.75f,5,5},std::tuple{1.f,7,9},std::tuple{1.5f,10,10}})natural(scale,lo,hi);persistence();std::cout<<"PASS golden-key bag delivery\n";}catch(const std::exception &e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
